            if (!is_bool($ret)) {
                $messages[] = $ret;
                expValidator::setErrorField($fieldname);
                unset($post[$fieldname]);
            }
        }
    }

    if (count($messages) >= 1) expValidator::failAndReturnToForm($messages, $post);
}

